CREATE TABLE "organizations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"name" varchar(160) NOT NULL,"slug" varchar(100) NOT NULL UNIQUE,"active" boolean DEFAULT true NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL);
INSERT INTO "organizations" ("id","name","slug") VALUES ('00000000-0000-4000-8000-000000000001','SA Capital','sa-capital') ON CONFLICT DO NOTHING;
ALTER TABLE "users" ADD COLUMN "organization_id" uuid REFERENCES "organizations"("id");
UPDATE "users" SET "organization_id"='00000000-0000-4000-8000-000000000001' WHERE "organization_id" IS NULL;
ALTER TABLE "users" ALTER COLUMN "organization_id" SET NOT NULL;
CREATE TABLE "crm_pipelines" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"organization_id" uuid NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE,"name" varchar(120) NOT NULL,"description" text,"color" varchar(20) DEFAULT '#2563eb' NOT NULL,"position" integer DEFAULT 0 NOT NULL,"is_default" boolean DEFAULT false NOT NULL,"active" boolean DEFAULT true NOT NULL,"created_by" uuid REFERENCES "users"("id") ON DELETE SET NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "crm_pipeline_name_org_uidx" ON "crm_pipelines" ("organization_id","name");
CREATE INDEX "crm_pipelines_org_idx" ON "crm_pipelines" ("organization_id","active");
CREATE TABLE "crm_pipeline_stages" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"pipeline_id" uuid NOT NULL REFERENCES "crm_pipelines"("id") ON DELETE CASCADE,"name" varchar(100) NOT NULL,"color" varchar(20) DEFAULT '#64748b' NOT NULL,"position" integer DEFAULT 0 NOT NULL,"result_type" varchar(20) DEFAULT 'open' NOT NULL,"system_key" varchar(30),"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE INDEX "crm_pipeline_stages_pipeline_idx" ON "crm_pipeline_stages" ("pipeline_id","position");
CREATE UNIQUE INDEX "crm_pipeline_stage_system_uidx" ON "crm_pipeline_stages" ("pipeline_id","system_key") WHERE "system_key" IS NOT NULL;
INSERT INTO "crm_pipelines" ("id","organization_id","name","description","color","is_default") VALUES ('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000001','Pipeline padrão','Fluxo comercial migrado do CRM original','#2563eb',true) ON CONFLICT DO NOTHING;
INSERT INTO "crm_pipeline_stages" ("id","pipeline_id","name","color","position","result_type","system_key") VALUES ('00000000-0000-4000-8000-000000000011','00000000-0000-4000-8000-000000000010','Contato inicial','#3b82f6',0,'open','new'),('00000000-0000-4000-8000-000000000012','00000000-0000-4000-8000-000000000010','Reserva','#f59e0b',1,'open','reservation'),('00000000-0000-4000-8000-000000000013','00000000-0000-4000-8000-000000000010','Perdido','#ef4444',2,'lost','lost') ON CONFLICT DO NOTHING;
ALTER TABLE "crm_deals" ADD COLUMN "organization_id" uuid REFERENCES "organizations"("id"), ADD COLUMN "pipeline_id" uuid REFERENCES "crm_pipelines"("id"), ADD COLUMN "stage_id" uuid REFERENCES "crm_pipeline_stages"("id"), ADD COLUMN "email" varchar(320), ADD COLUMN "priority" varchar(12) DEFAULT 'medium' NOT NULL, ADD COLUMN "expected_close_at" timestamptz, ADD COLUMN "notes" text, ADD COLUMN "loss_reason" text, ADD COLUMN "result" varchar(20) DEFAULT 'open' NOT NULL;
UPDATE "crm_deals" SET "organization_id"='00000000-0000-4000-8000-000000000001',"pipeline_id"='00000000-0000-4000-8000-000000000010',"stage_id"=CASE "stage" WHEN 'reservation' THEN '00000000-0000-4000-8000-000000000012'::uuid WHEN 'lost' THEN '00000000-0000-4000-8000-000000000013'::uuid ELSE '00000000-0000-4000-8000-000000000011'::uuid END,"result"=CASE WHEN "stage"='lost' THEN 'lost' ELSE 'open' END WHERE "pipeline_id" IS NULL;
ALTER TABLE "crm_deals" ALTER COLUMN "organization_id" SET NOT NULL, ALTER COLUMN "pipeline_id" SET NOT NULL, ALTER COLUMN "stage_id" SET NOT NULL;
CREATE INDEX "crm_deals_pipeline_stage_idx" ON "crm_deals" ("organization_id","pipeline_id","stage_id");
CREATE TABLE "crm_activities" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"organization_id" uuid NOT NULL REFERENCES "organizations"("id"),"deal_id" uuid NOT NULL REFERENCES "crm_deals"("id") ON DELETE CASCADE,"owner_id" uuid NOT NULL REFERENCES "users"("id"),"type" varchar(30) NOT NULL,"title" varchar(180) NOT NULL,"due_at" timestamptz NOT NULL,"status" varchar(20) DEFAULT 'pending' NOT NULL,"notes" text,"completed_at" timestamptz,"created_by" uuid NOT NULL REFERENCES "users"("id"),"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE INDEX "crm_activities_org_due_idx" ON "crm_activities" ("organization_id","status","due_at");
CREATE INDEX "crm_activities_deal_idx" ON "crm_activities" ("deal_id","due_at");
